/**
 * Com o fof/pages: qual página vira as Diretrizes, e o botão que cria a página
 * "Diretrizes" com o texto atual. Escolhida uma página, o texto abaixo deixa
 * de valer e o conteúdo passa a ser editado no fof/pages.
 */
class GuidelinesPagePicker extends AdminComponent {
  pages = null;
  creating = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/pages`,
      params: {
        'page[limit]': 50
      }
    }).then(res => {
      this.pages = (res?.data || []).map(p => ({
        id: String(p.id),
        title: String(p.attributes?.title || p.id)
      }));
      m.redraw();
    }).catch(() => {
      this.pages = [];
      m.redraw();
    });
  }
  create() {
    this.creating = true;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/canela-about-pages/guidelines`
    }).then(res => {
      app.data.settings['canela.guidelines_page'] = String(res.data.id);
      this.load();
    }).finally(() => {
      this.creating = false;
      m.redraw();
    });
  }
  view() {
    const current = getStr('canela.guidelines_page');
    const page = this.pages?.find(p => p.id === current);
    return m("div", {
      className: "Form-group CanelaAdmin-guidelinesPage"
    }, m("label", null, trans(`${KEY}.guidelines_page_label`)), m("select", {
      className: "FormControl",
      value: current,
      disabled: this.pages === null,
      onchange: e => {
        const value = e.target.value;
        app.data.settings['canela.guidelines_page'] = value;
        saveSetting({
          'canela.guidelines_page': value
        });
      }
    }, m("option", {
      value: ""
    }, trans(`${KEY}.guidelines_page_none`)), (this.pages || []).map(p => m("option", {
      value: p.id
    }, p.title))), m("p", {
      className: "helpText"
    }, trans(`${KEY}.guidelines_page_help`)), !page && m(Button, {
      className: "Button",
      loading: this.creating,
      disabled: this.pages === null,
      onclick: () => this.create()
    }, trans(`${KEY}.guidelines_page_create`)));
  }
}

