/*
 * Card do "Me too" no grupo "Tópico": o liga/desliga, em quais categorias e
 * etiquetas o botão aparece (o padrão
 * é todas), se some com a melhor resposta e se quem marca passa a
 * seguir o tópico. As chaves são `canela.metoo_*`, de extend/metoo.php.
 */
import app from 'flarum/admin/app';
import isExtensionEnabled from 'flarum/admin/utils/isExtensionEnabled';
import { AdminNotice } from '../components/AdminCard';
import AdminToggle from '../components/AdminToggle';
import { AdminComponent, getStr, saveSetting, trans } from '../util';
const KEY = 'ramon-canela.admin.settings.metoo';
const TAGS_SETTING = 'canela.metoo_tags';
const toggle = (name, extension) => m(AdminToggle, {
  settingKey: `canela.metoo_${name}`,
  label: trans(`${KEY}.${name}_label`),
  help: trans(`${KEY}.${name}_help`),
  extension: extension
});
/** As tags carregam uma vez por visita ao admin; o card redesenha várias. */
let tagRows = null;
let tagsLoading = false;
function loadTags() {
  if (tagRows || tagsLoading) return;
  tagsLoading = true;
  app.store.find('tags', {
    include: 'parent'
  }).then(tags => {
    // Primárias em ordem, cada uma seguida das filhas; as secundárias (sem
    // posição) no fim, em ordem alfabética, como na página de tags.
    const all = [...tags];
    const primary = all.filter(tag => tag.position() !== null && !tag.parent()).sort((a, b) => a.position() - b.position());
    const rows = [];
    const row = (tag, depth) => ({
      id: String(tag.id()),
      name: tag.name(),
      color: tag.color() || '',
      depth
    });
    for (const tag of primary) {
      rows.push(row(tag, 0));
      all.filter(child => child.parent() === tag).sort((a, b) => (a.position() ?? 0) - (b.position() ?? 0)).forEach(child => rows.push(row(child, 1)));
    }
    all.filter(tag => tag.position() === null && !tag.parent()).sort((a, b) => a.name().localeCompare(b.name())).forEach(tag => rows.push(row(tag, 0)));
    tagRows = rows;
  }).catch(() => {
    tagRows = [];
  }).finally(() => {
    tagsLoading = false;
    m.redraw();
  });
}

/**
 * A lista de tags com caixas de seleção. Nenhuma marcada = todas: assim um
 * fórum novo ganha o botão em todo tópico, e quem quer o botão só em
 * algumas (Suporte, Bug…) marca as dele.
 */
class AdminTagPicker extends AdminComponent {
  oninit(vnode) {
    super.oninit(vnode);
    loadTags();
  }
  view() {
    const selected = new Set(getStr(TAGS_SETTING).split(',').map(id => id.trim()).filter(Boolean));
    const save = next => {
      const value = [...next].join(',');
      app.data.settings[TAGS_SETTING] = value;
      saveSetting({
        [TAGS_SETTING]: value
      });
    };
    return m("div", {
      className: "Form-group CanelaAdmin-tagPicker"
    }, m("label", null, trans(`${KEY}.tags_label`)), m("p", {
      className: "helpText"
    }, trans(`${KEY}.tags_help`)), !tagRows ? m("p", {
      className: "helpText"
    }, trans(`${KEY}.tags_loading`)) : m('[', null, m("p", {
      className: "CanelaAdmin-tagPicker-summary"
    }, selected.size ? trans(`${KEY}.tags_some`, {
      count: selected.size
    }) : trans(`${KEY}.tags_all`), selected.size > 0 && m("button", {
      type: "button",
      className: "Button Button--link",
      onclick: () => save(new Set())
    }, trans(`${KEY}.tags_clear`))), m("ul", {
      className: "CanelaAdmin-tagPicker-list"
    }, tagRows.map(tag => m("li", {
      key: tag.id,
      className: tag.depth ? 'is-child' : ''
    }, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: selected.has(tag.id),
      onchange: event => {
        const next = new Set(selected);
        event.target.checked ? next.add(tag.id) : next.delete(tag.id);
        save(next);
      }
    }), m("span", {
      className: "CanelaAdmin-tagPicker-swatch",
      style: {
        background: tag.color || 'var(--control-bg)'
      }
    }), tag.name))))));
  }
}
const cards = [{
  id: 'metoo',
  group: 'topic',
  icon: 'far fa-hand',
  title: () => trans(`${KEY}.title`),
  description: () => trans(`${KEY}.enabled_help`),
  keywords: 'me too eu também mão hand problema compartilhado shared issue suporte support bug votar voto',
  master: 'canela.metoo_enabled',
  body: () => m('[', null, isExtensionEnabled('flarum-tags') && m(AdminTagPicker, null), toggle('hide_solved', 'fof-best-answer'), toggle('follow', 'flarum-subscriptions'), !isExtensionEnabled('fof-best-answer') && m(AdminNotice, null, trans(`${KEY}.no_best_answer_notice`)))
}];
export default cards;
flarum.reg.add('ramon-canela', 'admin/features/metoo', cards);